{
  "name": "monitoring-scholarship-app",
  "private": true,
  "type": "module",
  "workspaces": [
    "apps/*",
    "packages/*"
  ],
  "scripts": {
    "dev": "turbo dev",
    "build": "turbo build",
    "check-types": "turbo check-types",
    "dev:web": "turbo -F web dev",
    "dev:server": "turbo -F server dev",
    "db:push": "turbo -F @monitoring-scholarship-app/db db:push",
    "db:studio": "turbo -F @monitoring-scholarship-app/db db:studio",
    "db:generate": "turbo -F @monitoring-scholarship-app/db db:generate",
    "db:migrate": "turbo -F @monitoring-scholarship-app/db db:migrate",
    "test": "pnpm --filter web test && pnpm --filter server test && pnpm --filter @monitoring-scholarship-app/api test"
  },
  "packageManager": "pnpm@10.17.1",
  "pnpm": {
    "overrides": {
      "kysely": "0.28.17"
    }
  },
  "dependencies": {
    "dotenv": "catalog:",
    "zod": "catalog:",
    "@monitoring-scholarship-app/env": "workspace:*"
  },
  "devDependencies": {
    "typescript": "^6.0.3",
    "@types/node": "catalog:",
    "@monitoring-scholarship-app/config": "workspace:*",
    "turbo": "2.10.11"
  }
}

