{
  "name": "@monitoring-scholarship-app/db",
  "type": "module",
  "exports": {
    ".": {
      "default": "./src/index.ts"
    },
    "./*": {
      "default": "./src/*.ts"
    }
  },
  "scripts": {
    "check-types": "tsc --noEmit --declaration false --declarationMap false --composite false",
    "postinstall": "prisma generate",
    "db:push": "prisma db push",
    "db:generate": "prisma generate",
    "db:migrate": "prisma migrate dev",
    "db:studio": "prisma studio"
  },
  "devDependencies": {
    "prisma": "^7.9.1",
    "typescript": "^6.0.3",
    "@monitoring-scholarship-app/config": "workspace:*"
  },
  "dependencies": {
    "@prisma/client": "catalog:",
    "@prisma/adapter-neon": "^7.9.1",
    "@neondatabase/serverless": "^1.1.0",
    "dotenv": "catalog:",
    "zod": "catalog:",
    "@monitoring-scholarship-app/env": "workspace:*"
  }
}
